import { defineTool as defineTool2, ToolError as ToolError2 } from "npm:@lovable.dev/mcp-js@3.0.4";
import { z as z2 } from "npm:zod@^3.25.76";
var services = data_default.services;
var blogPosts = data_default.blogPosts;
var listServices = defineTool2({
  name: "list_services",
  title: "List services",
  description: "List WOODEX services (custom design, B2B fitouts, delivery, etc.) with their process steps.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const list = services.map((s) => ({
      slug: s.slug,
      title: s.title,
      process: s.process.map((p) => ({ step: p.step, title: p.title, description: p.description }))
    }));
    return { content: [{ type: "text", text: JSON.stringify(list) }], structuredContent: { services: list } };
  }
});
var listBlogPosts = defineTool2({
  name: "list_blog_posts",
  title: "List blog posts",
  description: "List WOODEX blog articles with id, title, excerpt and date.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const list = blogPosts.map((p) => ({ id: p.id, title: p.title, excerpt: p.excerpt, category: p.category, date: p.date }));
    return { content: [{ type: "text", text: JSON.stringify(list) }], structuredContent: { posts: list } };
  }
});
var getBlogPost = defineTool2({
  name: "get_blog_post",
  title: "Read blog post",
  description: "Read the full text of a WOODEX blog article by id.",
  inputSchema: { id: z2.string().min(1).describe("Blog post id.") },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const p = blogPosts.find((x) => x.id === id);
    if (!p) throw new ToolError2(`No blog post with id "${id}"`);
    const text = `# ${p.title}

` + p.content.map((c) => (c.heading ? `## ${c.heading}

` : "") + c.body).join("\n\n");
    return { content: [{ type: "text", text }] };
  }
});

// src/lib/mcp/index.ts
var mcp_default = defineMcp({
  name: "woodex-reimagined",
  title: "WOODEX Reimagined",
  version: "0.1.0",
  instructions: "Public catalog tools for WOODEX, a Lahore furniture maker. Prices are in PKR. Use search_products / get_product for furniture, list_categories_and_series for taxonomy, list_services for services, and list_blog_posts / get_blog_post for articles.",
  tools: [searchProducts, getProduct, listCategories, listServices, listBlogPosts, getBlogPost]
});

// lovable-mcp-supabase-entry.ts
import { createSupabaseHandler } from "npm:@lovable.dev/mcp-js@3.0.4/stacks/supabase";
Deno.serve(createSupabaseHandler(mcp_default, { functionName: "mcp" }));
